svg.script:
(() => {
  const root = document.documentElement;
  const layers = [...root.querySelectorAll('.depth')];
  const reduced = matchMedia('(prefers-reduced-motion: reduce)');
  let targetX=0, targetY=0, x=0, y=0, raf=0, enabled=true, strength=1, paused=false, optedIn=root.dataset.motion==="enabled";
  const motionBlocked=()=>reduced.matches && !optedIn;
  function render() {
    raf=0;
    if (motionBlocked() || paused || !enabled) return;
    x+=(targetX-x)*.085; y+=(targetY-y)*.085;
    layers.forEach(layer => {
      const d=Number(layer.dataset.depth);
      layer.style.setProperty('--dx',`${(x*d).toFixed(3)}px`);
      layer.style.setProperty('--dy',`${(y*d).toFixed(3)}px`);
    });
    if (Math.abs(targetX-x)+Math.abs(targetY-y)>.02) raf=requestAnimationFrame(render);
  }
  function schedule(){ if(!raf && !paused && enabled && !motionBlocked()) raf=requestAnimationFrame(render); }
  function reset(){ targetX=targetY=x=y=0; layers.forEach(l=>{l.style.removeProperty('--dx');l.style.removeProperty('--dy');}); }
  root.addEventListener('pointermove',e=>{
    if(!enabled || paused || motionBlocked()) return;
    const r=root.getBoundingClientRect();
    targetX=((e.clientX-r.left)/r.width-.5)*42*strength;
    targetY=((e.clientY-r.top)/r.height-.5)*28*strength;
    schedule();
  });
  root.addEventListener('pointerleave',()=>{targetX=targetY=0;schedule();});
  reduced.addEventListener('change',reset);
  window.sceneControls={
    pause(value){paused=Boolean(value);if(!paused && reduced.matches){optedIn=true;root.dataset.motion="enabled";}root.dataset.paused=String(paused);if(!paused)schedule();},
    parallax(value){enabled=Boolean(value);reset();},
    strength(value){strength=Math.max(0,Math.min(2,Number(value)||0));reset();},
    layer(id,visible){const layer=layers.find(l=>l.id===id);if(layer)layer.style.display=visible?'':'none';},
    layers:layers.map(l=>({id:l.id,label:l.dataset.label,depth:Number(l.dataset.depth)}))
  };
})();
